; String concatenation subroutine
str_concat:
    ; P1 = left string address
    ; Top of stack = right string address
    ; Returns result address in P0
    POP P2
    POP P3
    PUSH P2
    
    ; Allocate space for result string
    MOV P0,0x6000
    STRCPY P0,P1
    STRCAT P0,P3
    RET

; LEFT(string, count) - extract left count characters
left_substr:
    ; P0 = result buffer, P1 = source string, P2 = count
    MOV P3,P0
    MOV P4,0
left_loop:
    CMP P4,P2
    JZ left_done
    MOV P5,[P1]
    CMP P5,0
    JZ left_done
    MOV [P3],P5
    INC P1
    INC P3
    INC P4
    JMP left_loop
left_done:
    MOV [P3],0
    RET

; RIGHT(string, count) - extract right count characters
right_substr:
    ; P0 = result buffer, P1 = source string, P2 = count
    MOV P3,P1
    MOV P4,0
right_len_loop:
    MOV P5,[P3]
    CMP P5,0
    JZ right_len_done
    INC P3
    INC P4
