    JC right_use_all
    MOV P3,P4
    SUB P3,P2
    JMP right_copy
right_use_all:
    MOV P3,0
right_copy:
    ADD P1,P3
    MOV P3,P0
right_copy_loop:
    MOV P5,[P1]
    CMP P5,0
    JZ right_copy_done
    MOV [P3],P5
    INC P1
    INC P3
    JMP right_copy_loop
right_copy_done:
    MOV [P3],0
    RET

; MID(string, start, count) - extract substring
mid_substr:
