    MOV P4,P0
    MOV P5,0
mid_loop:
    CMP P5,P3
    JZ mid_done
    MOV P6,[P1]
    CMP P6,0
    JZ mid_done
    MOV [P4],P6
    INC P1
    INC P4
    INC P5
    JMP mid_loop
mid_done:
